const { shouldThrottle, throttleKey, recordDelivery } = require('./throttle');

const PREVIEW_LENGTH = 120;

/**
 * What one channel adds to the shared notifier pipeline.
 *
 * @typedef {object} ChannelStrategy
 * @property {string} channel Channel name, and the key of its function on `options.transport`.
 * @property {string} transportLabel Name used in the "transport is not configured" error.
 * @property {number} defaultMaxPerHour Hourly limit when `options.maxPerHour` is not set.
 * @property {(options: object) => object} settings Channel-specific settings with defaults applied.
 * @property {(user: object) => void} validateUser Throws a TypeError; runs after the shared user checks.
 * @property {(message: object, options: object) => boolean} [isThrottleExempt] Returning true skips all throttling.
 * @property {{ flag: string, label: string }} [marketingOptIn] User flag that marketing messages require.
 * @property {(formatted: object, user: object, message: object, options: object, notifier: object) => object} format
 *   Builds the transport payload from the shared formatted fields.
 */

function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

function formatCommon(notifier, user, message, options) {
  const id = `${notifier.channel}-${user.id}-${notifier.now().getTime()}`;
  const locale = options.locale || user.locale || notifier.defaultLocale;
  const title = applyTemplate(message.title, user, message);
  const body = applyTemplate(message.body, user, message);

  return {
    id,
    channel: notifier.channel,
    locale,
    title,
    body,
    preview: `${title}: ${body}`.slice(0, PREVIEW_LENGTH),
    metadata: {
      category: message.category || 'general',
      priority: message.priority || 'normal',
      generatedAt: notifier.now().toISOString()
    }
  };
}

async function deliver(notifier, strategy, payload) {
  if (typeof notifier.transport[strategy.channel] !== 'function') {
    throw new Error(`${strategy.transportLabel} transport is not configured`);
  }
  // Called as a method so a transport object that relies on `this` keeps it.
  await notifier.transport[strategy.channel](payload);
}

async function send(notifier, user, message, options) {
  notifier.validateUser(user);
  notifier.validateMessage(message);

  const throttle = notifier.shouldThrottle(user, message, options);
  if (throttle.throttled) {
    return {
      channel: notifier.channel,
      status: 'throttled',
      reason: throttle.reason,
      retryAt: throttle.retryAt,
      userId: user.id
    };
  }

  const formatted = notifier.format(user, message, options);
  await notifier.deliver(formatted, user, message, options);
  notifier.recordDelivery(user, message, options);

  return {
    channel: notifier.channel,
    status: 'sent',
    userId: user.id,
    id: formatted.id,
    preview: formatted.preview
  };
}

/**
 * Builds a notifier for one channel. Settings live as plain properties on the
 * returned object and are read at call time.
 *
 * @param {ChannelStrategy} strategy
 * @param {object} [options]
 */
function createChannelNotifier(strategy, options = {}) {
  const notifier = {
    channel: strategy.channel,
    transport: options.transport || {},
    // `templates` and `defaultSender` are not read by any channel; they stay
    // because callers could read them off the notifier.
    templates: options.templates || {},
    throttleStore: options.throttleStore || new Map(),
    now: options.now || (() => new Date()),
    defaultSender: options.defaultSender || 'Product Team',
    defaultLocale: options.defaultLocale || 'en-US',
    maxPerHour: options.maxPerHour || strategy.defaultMaxPerHour,
    ...strategy.settings(options)
  };

  // send() reaches each step through `notifier`, so replacing a step on one
  // instance (for example a stubbed `deliver`) changes what send() does.
  return Object.assign(notifier, {
    send: (user, message, sendOptions = {}) => send(notifier, user, message, sendOptions),
    validateUser: user => {
      validateUser(user);
      strategy.validateUser(user);
    },
    validateMessage,
    shouldThrottle: (user, message, sendOptions = {}) =>
      shouldThrottle(notifier, strategy, user, message, sendOptions),
    throttleKey: (user, message) => throttleKey(notifier, user, message),
    format: (user, message, sendOptions = {}) =>
      strategy.format(formatCommon(notifier, user, message, sendOptions), user, message, sendOptions, notifier),
    applyTemplate,
    recordDelivery: (user, message) => recordDelivery(notifier, user, message),
    deliver: payload => deliver(notifier, strategy, payload)
  });
}

module.exports = {
  createChannelNotifier
};

