  // instance (for example a stubbed `deliver`) changes what send() does.
  return Object.assign(notifier, {
    send: (user, message, sendOptions = {}) => send(notifier, user, message, sendOptions),
    validateUser: user => {
      validateUser(user);
      strategy.validateUser(user);
    },
    validateMessage,
    shouldThrottle: (user, message, sendOptions = {}) =>
      shouldThrottle(notifier, strategy, user, message, sendOptions),
    throttleKey: (user, message) => throttleKey(notifier, user, message),
    format: (user, message, sendOptions = {}) =>
      strategy.format(formatCommon(notifier, user, message, sendOptions), user, message, sendOptions, notifier),
    applyTemplate,
    recordDelivery: (user, message) => recordDelivery(notifier, user, message),
    deliver: payload => deliver(notifier, strategy, payload)
  });
}

