const E164_PHONE = /^\+[1-9]\d{6,14}$/;

function truncate(value, maxLength) {
  if (value.length <= maxLength) {
    return value;
  }
  return `${value.slice(0, maxLength - 1)}…`;
}

module.exports = {
  channel: 'sms',
  transportLabel: 'sms',
  defaultMaxPerHour: 4,
  marketingOptIn: { flag: 'smsOptIn', label: 'SMS' },

  settings(options) {
    return {
      senderId: options.senderId || 'APP',
      segmentLength: options.segmentLength || 140
    };
  },

  validateUser(user) {
    if (!user.phone || !E164_PHONE.test(user.phone)) {
      throw new TypeError('user.phone must be E.164 for SMS notifications');
    }
  },

  format(formatted, user, message, options, notifier) {
    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    const text = truncate(`${prefix}${formatted.title} - ${formatted.body}`, notifier.segmentLength);

    return {
      ...formatted,
      to: user.phone,
      from: notifier.senderId,
      text,
      segments: Math.ceil(text.length / notifier.segmentLength),
      preview: text
    };
  }
};

