const PREVIEW_LENGTH = 120;

function blocksFor(formatted, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${formatted.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: formatted.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${formatted.metadata.category}`
        }
      ]
    }
  ];
}

module.exports = {
  channel: 'slack',
  transportLabel: 'slack',
  defaultMaxPerHour: 20,

  settings(options) {
    return {
      defaultWorkspace: options.defaultWorkspace || 'main',
      defaultChannel: options.defaultChannel || '#general'
    };
  },

  validateUser(user) {
    if (!user.slackId && !user.slackChannel) {
      throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
    }
  },

  // Replies in an existing thread are never throttled.
  isThrottleExempt(message, options) {
    return Boolean(options.threadTs);
  },

  format(formatted, user, message, options, notifier) {
    const channel = options.channel || user.slackChannel || notifier.defaultChannel;
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${formatted.title}*\n${formatted.body}`;

    return {
      ...formatted,
      workspace: user.slackWorkspace || notifier.defaultWorkspace,
      channel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(formatted, mention),
      preview: text.replace(/\*/g, '').slice(0, PREVIEW_LENGTH)
    };
  }
};

