const URGENT_EXPIRY_HOURS = 72;
const DEFAULT_EXPIRY_HOURS = 168;

module.exports = {
  channel: 'inapp',
  transportLabel: 'in-app',
  defaultMaxPerHour: 50,

  settings(options) {
    return {
      defaultIcon: options.defaultIcon || 'bell',
      defaultAction: options.defaultAction || '/notifications'
    };
  },

  validateUser(user) {
    if (user.disabledInApp) {
      throw new TypeError('in-app notifications are disabled for this user');
    }
  },

  // Security notices always reach the inbox, whatever the hourly limit.
  isThrottleExempt(message) {
    return message.category === 'security';
  },

  format(formatted, user, message, options, notifier) {
    const defaultHours = message.priority === 'urgent' ? URGENT_EXPIRY_HOURS : DEFAULT_EXPIRY_HOURS;
    const expiresInHours = options.expiresInHours || defaultHours;
    const expiresAt = new Date(notifier.now().getTime() + expiresInHours * 60 * 60 * 1000);

    return {
      ...formatted,
      userId: user.id,
      icon: message.icon || notifier.defaultIcon,
      actionUrl: options.actionUrl || message.actionUrl || notifier.defaultAction,
      read: false,
      expiresAt: expiresAt.toISOString(),
      preview: formatted.title
    };
  }
};

