const email = require('./channels/email');
const sms = require('./channels/sms');
const slack = require('./channels/slack');
const inapp = require('./channels/inapp');
const { createChannelNotifier } = require('./channelNotifier');

// Maps each channel name to its strategy (see ChannelStrategy in channelNotifier.js).
const registry = {
  email,
  sms,
  slack,
  inapp
};

function createNotifier(channel, options = {}) {
  // hasOwn keeps names like "constructor" from resolving to Object.prototype members.
  const strategy = Object.hasOwn(registry, channel) && registry[channel];
  if (!strategy) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return createChannelNotifier(strategy, options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};

