// Differential check: runs identical scenarios against the original class-based
// implementation and the refactored one, then compares serialized traces.
const path = require('node:path');

const ORIGINAL = path.join(__dirname, 'original/src/notifications');
const REFACTORED = process.argv[2];

function serialize(value) {
  const seen = new WeakSet();
  return JSON.stringify(value, function replacer(key, v) {
    if (v === undefined) return '__undefined__';
    if (typeof v === 'function') return '__function__';
    if (v instanceof Map) return { __map__: [...v.entries()] };
    if (v instanceof Error) return { __error__: v.constructor.name, message: v.message };
    if (v && typeof v === 'object') {
      if (seen.has(v)) return '__cycle__';
      seen.add(v);
    }
    return v;
  });
}

function counterClock(startIso = '2026-01-02T03:04:05.000Z', stepMs = 1000) {
  const start = new Date(startIso).getTime();
  const calls = [];
  const now = () => {
    const d = new Date(start + calls.length * stepMs);
    calls.push(d.toISOString());
    return d;
  };
  return { now, calls };
}

function makeTransport(log, { omit = [], throwOn = [] } = {}) {
  const transport = {};
  for (const ch of ['email', 'sms', 'slack', 'inapp']) {
    if (omit.includes(ch)) continue;
    transport[ch] = async payload => {
      if (throwOn.includes(ch)) throw new Error(`boom-${ch}`);
      log.push([ch, payload]);
      return 'ignored-return';
    };
  }
  return transport;
}

// A transport whose methods need `this`.
function makeBoundTransport(log) {
  return {
    sink: log,
    async email(p) { this.sink.push(['email', p]); },
    async sms(p) { this.sink.push(['sms', p]); },
    async slack(p) { this.sink.push(['slack', p]); },
    async inapp(p) { this.sink.push(['inapp', p]); }
  };
}

async function capture(fn) {
  try {
    return { ok: await fn() };
  } catch (err) {
    return { err: { name: err.constructor.name, message: err.message } };
  }
}

function dataProps(notifier) {
  const out = {};
  for (const key of Object.keys(notifier).sort()) {
    const v = notifier[key];
    if (typeof v === 'function') continue;
    if (key === 'throttleStore') out[key] = v instanceof Map ? 'Map' : typeof v;
    else if (key === 'transport' || key === 'templates') out[key] = Object.keys(v).sort();
    else out[key] = v;
  }
  return out;
}

const USERS = {
  email: [
    { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
    { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: false },
    { id: 'u&1 ?x', email: 'odd@example.com', locale: 'fr-FR' },
    { id: 'u1', email: 'no-at-sign' },
    { id: 'u1' },
    { name: 'no id', email: 'a@b.c' },
    null,
    'string-user',
    { id: 'u1', name: '$& $1 {{id}}', email: 'dollar@example.com' }
  ],
  sms: [
    { id: 'u2', name: 'Bo', phone: '+15551234567', smsOptIn: true },
    { id: 'u2', phone: '+15551234567', smsOptIn: false },
    { id: 'u2', phone: '555-1212' },
    { id: 'u2', phone: '+0123456789' },
    { id: 'u2' },
    { phone: '+15551234567' },
    null
  ],
  slack: [
    { id: 'u3', slackId: 'U123', slackWorkspace: 'eng' },
    { id: 'u3', slackChannel: '#alerts' },
    { id: 'u3', slackId: 'U123', slackChannel: '#alerts' },
    { id: 'u3' },
    null
  ],
  inapp: [
    { id: 'u4', name: 'Dee' },
    { id: 'u4', disabledInApp: true },
    { id: 'u4', locale: 'de-DE' },
    { disabledInApp: true },
    null
  ]
};

const MESSAGES = [
  { title: 'Hello {{name}}', body: 'Your {{category}} update for {{id}} is ready', category: 'transactional' },
  { title: 'Deal', body: 'Save now', category: 'marketing' },
  { title: 'Deal', body: 'Urgent save', category: 'marketing', priority: 'urgent' },
  { title: 'Login', body: '<script>"&"</script>', category: 'security' },
  { title: 'Plain', body: 'No category' },
  { title: 'Deploy', body: 'Finished', category: 'release', priority: 'urgent', icon: 'rocket', actionUrl: '/deploys' },
  { title: 'T'.repeat(80), body: 'B'.repeat(200), category: 'general', priority: 'low' },
  { title: '😀'.repeat(30), body: 'é'.repeat(150) },
  { title: '', body: 'missing title' },
  { title: 'missing body' },
  null,
  42
];

const SEND_OPTIONS = [
  undefined,
  {},
  { force: true },
  { threadTs: '171234.0001', channel: '#ops' },
  { locale: 'es-ES', actionUrl: '/security', expiresInHours: 2 },
  { expiresInHours: 0.1 },
  { expiresInHours: 1 / 3 },
  { expiresInHours: '5' }
];

const CONSTRUCT_OPTIONS = [
  () => ({}),
  () => ({ maxPerHour: 1 }),
  () => ({ maxPerHour: 0 }),
  () => ({ maxPerHour: 2, channel: 'bogus', templates: { a: 1 }, defaultSender: 'Ops', defaultLocale: 'en-GB' }),
  () => ({
    from: 'alerts@example.com',
    replyTo: 'help@example.com',
    unsubscribeBaseUrl: 'https://u.example/x',
    senderId: 'ACME',
    segmentLength: 40,
    defaultWorkspace: 'product',
    defaultChannel: '#random',
    defaultIcon: 'star',
    defaultAction: '/inbox'
  }),
  () => ({ segmentLength: 7 })
];

async function runScenarios(lib) {
  const trace = [];
  const channels = ['email', 'sms', 'slack', 'inapp'];

  // Factory surface.
  trace.push(['registry keys', Object.keys(lib.registry)]);
  for (const name of ['fax', '', undefined, null, 'toString', '__proto__', 'hasOwnProperty']) {
    trace.push(['createNotifier unknown', String(name), await capture(() => lib.createNotifier(name))]);
  }
  {
    const store = new Map();
    const clock = counterClock();
    const log = [];
    const all = lib.createAllNotifiers({ transport: makeTransport(log), throttleStore: store, now: clock.now, maxPerHour: 1 });
    trace.push(['createAllNotifiers keys', Object.keys(all)]);
    for (const ch of channels) trace.push(['createAll props', ch, dataProps(all[ch]), all[ch].throttleStore === store]);
    const users = { email: USERS.email[0], sms: USERS.sms[0], slack: USERS.slack[0], inapp: USERS.inapp[0] };
    for (const ch of channels) {
      for (let i = 0; i < 2; i += 1) {
        trace.push(['createAll send', ch, i, await capture(() => all[ch].send(users[ch], MESSAGES[4]))]);
      }
    }
    trace.push(['createAll store/log/clock', serialize(store), serialize(log), clock.calls]);
  }
  {
    const a = lib.createAllNotifiers();
    trace.push(['createAll separate default stores', a.email.throttleStore !== a.sms.throttleStore, dataProps(a.slack)]);
  }

  // Full matrix of send() through each channel.
  for (const ch of channels) {
    for (const [ci, makeOpts] of CONSTRUCT_OPTIONS.entries()) {
      for (const [ui, user] of USERS[ch].entries()) {
        for (const [mi, message] of MESSAGES.entries()) {
          for (const [si, sendOptions] of SEND_OPTIONS.entries()) {
            const clock = counterClock();
            const log = [];
            const store = new Map();
            const notifier = lib.createNotifier(ch, { ...makeOpts(), transport: makeTransport(log), throttleStore: store, now: clock.now });
            const results = [];
            for (let i = 0; i < 3; i += 1) {
              results.push(await capture(() =>
                sendOptions === undefined ? notifier.send(user, message) : notifier.send(user, message, sendOptions)));
            }
            trace.push([ch, ci, ui, mi, si, serialize(results), serialize(log), serialize(store), clock.calls]);
          }
        }
      }
    }
  }

  // Instance data, direct method calls, and transport edge cases.
  for (const ch of channels) {
    const user = USERS[ch][0];
    const message = MESSAGES[0];
    for (const makeOpts of CONSTRUCT_OPTIONS) {
      trace.push(['props', ch, dataProps(lib.createNotifier(ch, makeOpts()))]);
    }

    const clock = counterClock();
    const log = [];
    const n = lib.createNotifier(ch, { transport: makeTransport(log), now: clock.now });
    trace.push(['format', ch, serialize(await capture(() => n.format(user, message)))]);
    trace.push(['format opts', ch, serialize(await capture(() => n.format(user, message, SEND_OPTIONS[4])))]);
    trace.push(['shouldThrottle', ch, serialize(await capture(() => n.shouldThrottle(user, MESSAGES[1])))]);
    trace.push(['throttleKey', ch, n.throttleKey(user, message), n.throttleKey(user, MESSAGES[4])]);
    trace.push(['applyTemplate', ch, n.applyTemplate('{{name}}/{{id}}/{{category}}', { id: 7 }, {})]);
    trace.push(['validateUser', ch, serialize(await capture(() => n.validateUser(user))), serialize(await capture(() => n.validateUser({})))]);
    trace.push(['validateMessage', ch, serialize(await capture(() => n.validateMessage({ title: 'a' })))]);
    n.recordDelivery(user, message);
    trace.push(['recordDelivery', ch, serialize(n.throttleStore)]);
    trace.push(['deliver', ch, serialize(await capture(() => n.deliver({ x: 1 }))), serialize(log)]);
    trace.push(['clock', ch, clock.calls]);

    for (const [label, transportOpts] of [
      ['no transport', undefined],
      ['missing fn', { omit: [ch] }],
      ['throws', { throwOn: [ch] }]
    ]) {
      const tlog = [];
      const store = new Map();
      const opts = { throttleStore: store, now: counterClock().now };
      if (transportOpts) opts.transport = makeTransport(tlog, transportOpts);
      const t = lib.createNotifier(ch, opts);
      trace.push(['transport', label, ch, serialize(await capture(() => t.send(user, message))), serialize(store), serialize(tlog)]);
    }

    const blog = [];
    const b = lib.createNotifier(ch, { transport: makeBoundTransport(blog), now: counterClock().now });
    trace.push(['bound transport', ch, serialize(await capture(() => b.send(user, message))), blog.length]);

    // Per-instance overrides of pipeline steps.
    const o = lib.createNotifier(ch, { now: counterClock().now, maxPerHour: 1 });
    const stubbed = [];
    o.deliver = async payload => { stubbed.push(payload.id); };
    trace.push(['override deliver', ch, serialize(await capture(() => o.send(user, message))), stubbed]);
    o.maxPerHour = 5;
    trace.push(['mutated maxPerHour', ch, serialize(await capture(() => o.send(user, message)))]);

    // Wall-clock default `now` still yields a string id and ISO timestamps.
    const w = lib.createNotifier(ch, { transport: makeTransport([]) });
    const wr = await w.send(user, message);
    trace.push(['default clock', ch, wr.status, /^\w+-.+-\d+$/.test(wr.id)]);
  }

  // Rate-limit window: entries older than an hour stop counting.
  for (const ch of channels) {
    let t = new Date('2026-01-02T00:00:00.000Z').getTime();
    const store = new Map();
    const n = lib.createNotifier(ch, { transport: makeTransport([]), throttleStore: store, maxPerHour: 2, now: () => new Date(t) });
    const user = USERS[ch][0];
    const out = [];
    for (const step of [0, 10, 10, 30 * 60 * 1000, 30 * 60 * 1000 - 20, 1, 1, 60 * 60 * 1000]) {
      t += step;
      out.push(serialize(await capture(() => n.send(user, MESSAGES[4]))));
    }
    trace.push(['window', ch, out, serialize(store)]);
  }

  // A caller-owned options object must not be mutated.
  const callerOptions = { maxPerHour: 2, transport: makeTransport([]) };
  const before = serialize(callerOptions);
  lib.createAllNotifiers(callerOptions);
  trace.push(['options untouched', serialize(callerOptions) === before]);

  return trace;
}

async function main() {
  const original = await runScenarios(require(ORIGINAL));
  const refactored = await runScenarios(require(REFACTORED));

  let diffs = 0;
  const max = Math.max(original.length, refactored.length);
  for (let i = 0; i < max; i += 1) {
    const a = serialize(original[i]);
    const b = serialize(refactored[i]);
    if (a !== b) {
      diffs += 1;
      if (diffs <= 15) {
        console.log(`DIFF #${i}\n  original:   ${a.slice(0, 600)}\n  refactored: ${b.slice(0, 600)}`);
      }
    }
  }
  console.log(`scenarios compared: ${max}, differences: ${diffs}`);
  process.exitCode = diffs === 0 ? 0 : 1;
}

main().catch(err => {
  console.error('harness failed', err);
  process.exitCode = 2;
});

