// Differential check: runs identical scenarios against the original class-based
// implementation and the refactored one, then compares serialized traces.
const path = require('node:path');

const ORIGINAL = path.join(__dirname, 'original/src/notifications');
const REFACTORED = process.argv[2];

function serialize(value) {
  const seen = new WeakSet();
  return JSON.stringify(value, function replacer(key, v) {
    if (v === undefined) return '__undefined__';
    if (typeof v === 'function') return '__function__';
    if (v instanceof Map) return { __map__: [...v.entries()] };
    if (v instanceof Error) return { __error__: v.constructor.name, message: v.message };
    if (v && typeof v === 'object') {
      if (seen.has(v)) return '__cycle__';
      seen.add(v);
    }
    return v;
  });
}

function counterClock(startIso = '2026-01-02T03:04:05.000Z', stepMs = 1000) {
  const start = new Date(startIso).getTime();
  const calls = [];
  const now = () => {
    const d = new Date(start + calls.length * stepMs);
    calls.push(d.toISOString());
    return d;
  };
  return { now, calls };
}

function makeTransport(log, { omit = [], throwOn = [] } = {}) {
  const transport = {};
  for (const ch of ['email', 'sms', 'slack', 'inapp']) {
    if (omit.includes(ch)) continue;
    transport[ch] = async payload => {
      if (throwOn.includes(ch)) throw new Error(`boom-${ch}`);
      log.push([ch, payload]);
      return 'ignored-return';
    };
  }
  return transport;
}

// A transport whose methods need `this`.
function makeBoundTransport(log) {
  return {
    sink: log,
    async email(p) { this.sink.push(['email', p]); },
    async sms(p) { this.sink.push(['sms', p]); },
    async slack(p) { this.sink.push(['slack', p]); },
    async inapp(p) { this.sink.push(['inapp', p]); }
  };
}

async function capture(fn) {
  try {
    return { ok: await fn() };
  } catch (err) {
    return { err: { name: err.constructor.name, message: err.message } };
  }
}

function dataProps(notifier) {
  const out = {};
  for (const key of Object.keys(notifier).sort()) {
    const v = notifier[key];
    if (typeof v === 'function') continue;
    if (key === 'throttleStore') out[key] = v instanceof Map ? 'Map' : typeof v;
    else if (key === 'transport' || key === 'templates') out[key] = Object.keys(v).sort();
    else out[key] = v;
  }
  return out;
}

